 public function testExplicitLinesAndCurrentDependenciesFailClosed():void {
  $args=$this->orderFixture();$class=\DigiForge\Connector\Printify\NativeBusinessOrderEvidence::class;$scope=$args[0];$assoc=$args[4];global $wpdb;$plan=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::fulfillment_plans().' WHERE id=%d',$args[3]),ARRAY_A);$order=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::orders().' WHERE id=%d',$args[1]),ARRAY_A);$version=(int)$assoc[0]['product_version_id'];$localLine=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::order_line_items().' WHERE id=%d',$assoc[0]['local_line_id']),ARRAY_A);$v=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::product_versions().' WHERE id=%d',$version),ARRAY_A);
  foreach(['missing','duplicate','swapped','quantity','cross_shop','plan','dependency','uncertain','outer_transaction','stale_source','temporary_shadow','listed_mismatch']as $mode){$a=$args;$filter=null;
   if($mode==='listed_mismatch')$wpdb->update(Tables::order_line_items(),['listing_id'=>2147483647],['id'=>$assoc[0]['local_line_id']],['%d'],['%d']);if($mode==='missing')$a[4]=[];if($mode==='duplicate')$a[4][]=$assoc[0];if($mode==='swapped')$a[4][0]['local_line_id']+=100000;if($mode==='quantity')$a[4][0]['quantity']=99;if($mode==='cross_shop')$wpdb->update(Tables::orders(),['shop_reference'=>'standard_pod'],['id'=>$args[1]],['%s'],['%d']);if($mode==='plan')$wpdb->update(Tables::fulfillment_plans(),['canonical_payload'=>'{}'],['id'=>$args[3]],['%s'],['%d']);if($mode==='dependency')$wpdb->update(Tables::product_versions(),['state'=>'REVIEW'],['id'=>$version],['%s'],['%d']);if($mode==='stale_source'){$sourceKey='digiforge_api_read_receipt_'.$args[2];$sourceRaw=$wpdb->get_var($wpdb->prepare('SELECT option_value FROM '.$wpdb->options.' WHERE option_name=%s',$sourceKey));$wpdb->update($wpdb->options,['option_value'=>'{}'],['option_name'=>$sourceKey],['%s'],['%s']);}if($mode==='temporary_shadow'){$ddl=$wpdb->get_row('SHOW CREATE TABLE '.Tables::orders(),ARRAY_N);$wpdb->query(preg_replace('/^CREATE TABLE/','CREATE TEMPORARY TABLE',$ddl[1]));}if($mode==='outer_transaction')$wpdb->query('START TRANSACTION');if($mode==='uncertain'){$filter=static fn($q)=>str_contains($q,'SELECT * FROM '.Tables::order_line_items())?'SELECT * FROM missing_order_read':$q;add_filter('query',$filter);}
   try{self::assertWPError($class::prepareEvidence($scope,1,...array_slice($a,1)),$mode);}finally{if($mode==='listed_mismatch')$wpdb->update(Tables::order_line_items(),$localLine,['id'=>$assoc[0]['local_line_id']],array_fill(0,count($localLine),'%s'),['%d']);if($mode==='temporary_shadow')$wpdb->query('DROP TEMPORARY TABLE '.Tables::orders());if($mode==='stale_source')$wpdb->update($wpdb->options,['option_value'=>$sourceRaw],['option_name'=>$sourceKey],['%s'],['%s']);if($filter)remove_filter('query',$filter);if($mode==='outer_transaction')$wpdb->query('ROLLBACK');$wpdb->update(Tables::fulfillment_plans(),$plan,['id'=>$args[3]],array_fill(0,count($plan),'%s'),['%d']);$wpdb->update(Tables::orders(),$order,['id'=>$args[1]],array_fill(0,count($order),'%s'),['%d']);$wpdb->update(Tables::product_versions(),$v,['id'=>$version],array_fill(0,count($v),'%s'),['%d']);}
  }
  self::assertTrue(\DigiForge\Core\Settings::safety_locked());
 }

